function isMultiline(str) {
  return str.includes("\n");
}

function escapeForTemplateLiteral(str) {
  // In a template literal, we need to escape:
  // 1. Backslashes (\ -> \\)
  // 2. Backticks (` -> \`)
  // 3. ${  -> \${
  return str
    .replace(/\\/g, "\\\\")
    .replace(/`/g, "\\`")
    .replace(/\$\{/g, "\\${");
}

function escapeForDoubleQuote(str) {
  // In a double-quoted string, escape backslashes and double quotes
  return str.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

function toJsValue(val, indent) {
  if (val === null) {
    return "null";
  }
  if (typeof val === "boolean") {
    return val.toString();
  }
  if (typeof val === "number") {
    return val.toString();
  }
  if (typeof val === "string") {
    if (isMultiline(val)) {
      return "`" + escapeForTemplateLiteral(val) + "`";
    } else {
      return '"' + escapeForDoubleQuote(val) + '"';
    }
  }
  if (Array.isArray(val)) {
    if (val.length === 0) {
      return "[]";
    }
    const inner = indent + "  ";
    const items = val.map((item) => inner + toJsValue(item, inner));
    return "[\n" + items.join(",\n") + "\n" + indent + "]";
  }
  if (typeof val === "object") {
    const keys = Object.keys(val);
    if (keys.length === 0) {
      return "{}";
    }
    const inner = indent + "  ";
    const entries = keys.map((key) => {
      return inner + key + ": " + toJsValue(val[key], inner);
    });
    return "{\n" + entries.join(",\n") + "\n" + indent + "}";
  }
  return String(val);
}

// Build the output
let output = "";
output +=
  "// topics-1-3.js\n" +
  "// First 3 topics extracted from tutors.json (course.los[0], course.los[1], course.los[2])\n" +
